import {test,expect,type Page} from '@playwright/test';
import fixture from './fixtures/twin-lab.json';

// Snapshots generated by the real local TwinEngine, seed 42. No cloud data/model calls.
async function setup(page:Page,admin=true){
 const full:any=structuredClone(fixture.compared);let run:any=null;const calls:string[]=[];
 await page.route('**/api/**',async route=>{
  const path=new URL(route.request().url()).pathname,method=route.request().method();let data:any=[];
  if(path==='/api/config')data={user:{id:'qa-admin',role:admin?'ADMIN':'USER',kind:'ACCOUNT',displayName:'가상 Lab 검증 사용자',operatorId:'OP-01'},fictional:true,hermes:{},database:'H2 DEVELOPMENT',graph:'SQL_FALLBACK'};
  else if(path==='/api/catalog')data={assets:[],operators:[],scenarios:[],manuals:[]};
  else if(path==='/api/dashboard')data={total:0,active:0,byDay:{},byType:{},bySystem:{},systemStatus:[]};
  else if(path==='/api/graph')data={nodes:[],edges:[],engine:'SQL_FALLBACK'};
  else if(path==='/api/demo-control')data={allowed:false};
  else if(path==='/api/twin/catalog')data=fixture.catalog;
  else if(path==='/api/twin/runs'&&method==='POST'){calls.push('create');run={id:full.id,version:0,status:'NORMAL',seed:42,baseline:full.baseline,current:full.baseline,events:[],approvals:[],objective:'STABILITY'};data=run;}
  else if(path==='/api/twin/runs')data=run?[run]:[];
  else if(path.startsWith('/api/twin/runs/')){
   if(method==='POST'){
    const op=path.split('/').at(-1)!;calls.push(op);const body=route.request().postDataJSON();expect(body.version).toBe(run.version);run.version++;
    if(op==='inject'){run.status='FAULTED';run.current=full.faultSnapshot;run.faultSnapshot=full.faultSnapshot;}
    if(op==='analyze'){run.status='ANALYZED';run.analysis=full.analysis;}
    if(op==='strategies'){run.status='PLANNED';run.strategies=full.strategies;run.generation=full.generation;}
    if(op==='simulate'){run.status='COMPARED';run.results=full.results;run.recommendation=full.recommendation;}
    if(op==='request'){run.status='WAITING_APPROVAL';run.selectedStrategy=body.strategyId;}
    if(op==='decision'){run.status=body.approved?'APPROVED':'REJECTED';if(body.approved)run.current=full.results.find((r:any)=>r.strategyId===run.selectedStrategy).after;run.approvals.push({approved:body.approved,reason:body.reason,actor:'qa-admin',at:'2026-10-19T00:00:00Z'});}
    run.events.push({sequence:run.events.length+1,stage:op,message:`가상 ${op} 완료`,at:'2026-10-19T00:00:00Z'});
   }data=run;
  }
  await route.fulfill({json:data});
 });
 await page.goto('/');await page.getByRole('button',{name:'Digital Twin & Chaos Lab',exact:true}).click();await expect(page.getByRole('heading',{name:'가상 금융 서비스 의존 관계'})).toBeVisible();return calls;
}
test('automatic demo pauses, skips presentation only, and never auto-approves',async({page})=>{
 const errors:string[]=[];page.on('pageerror',e=>errors.push(e.message));const calls=await setup(page);
 await page.getByRole('button',{name:'자동 데모 실행',exact:true}).click();await expect(page.getByRole('button',{name:'일시정지',exact:true})).toBeEnabled();
 await page.getByRole('button',{name:'일시정지',exact:true}).click();await expect(page.getByRole('button',{name:'재개',exact:true})).toBeVisible();
 for(let i=0;i<6;i++){await page.getByRole('button',{name:'단계 건너뛰기',exact:true}).click();await expect(page.locator('.twin-busy')).toHaveCount(0);}
 await expect(page.getByRole('button',{name:'단계 건너뛰기',exact:true})).toBeDisabled();
 await expect(page.getByRole('button',{name:'승인 후 가상 결과 확정',exact:true})).toBeDisabled();expect(calls).not.toContain('decision');
 await page.screenshot({path:'test-results/twin-approval-desktop.png',fullPage:true});
 await page.getByLabel('승인·반려 사유',{exact:true}).fill('가상 Replica 상태와 복구 결과를 검토했습니다.');await page.getByRole('button',{name:'승인 후 가상 결과 확정',exact:true}).click();
 await expect(page.getByText('After · 승인 결과',{exact:true})).toBeVisible();await expect(page.getByRole('link',{name:'최종 보고서 JSON 다운로드'})).toHaveAttribute('href',/\/api\/twin\/runs\/.*\/report/);
 expect(calls.filter(c=>c==='decision')).toHaveLength(1);expect(errors).toEqual([]);
});
test('mobile lab graph, comparison and controls fit; motion can be disabled',async({page})=>{
 await page.setViewportSize({width:390,height:844});await setup(page);
 await page.getByLabel('애니메이션',{exact:true}).uncheck();await expect(page.locator('.twin-lab')).toHaveClass(/twin-reduced/);
 await page.getByRole('button',{name:'자동 데모 실행',exact:true}).click();await page.getByRole('button',{name:'일시정지',exact:true}).click();
 await page.getByRole('button',{name:'단계 건너뛰기',exact:true}).click();await expect(page.getByRole('heading',{name:'Chaos 장애 주입',exact:true})).toBeVisible();
 expect(await page.locator('body').evaluate(el=>el.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:'test-results/twin-chaos-mobile.png',fullPage:true});
 for(let i=0;i<4;i++){await page.getByRole('button',{name:'단계 건너뛰기',exact:true}).click();await expect(page.locator('.twin-busy')).toHaveCount(0);}
 await expect(page.getByRole('heading',{name:'복구 전략 비교·추천'})).toBeVisible();await expect(page.getByRole('table')).toContainText('복구 실패');await expect(page.getByRole('table')).toContainText('부분 복구');expect(await page.locator('body').evaluate(el=>el.scrollWidth<=innerWidth)).toBe(true);
 await page.screenshot({path:'test-results/twin-comparison-mobile.png',fullPage:true});
});
test('normal users cannot start an experiment and unexecuted evaluations are not shown',async({page})=>{
 const calls=await setup(page,false);await expect(page.getByRole('button',{name:'새 독립 실험',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'자동 데모 실행',exact:true})).toBeDisabled();await page.getByRole('button',{name:'8 AI 성능 평가',exact:true}).click();await expect(page.getByText('아직 실행된 평가가 없습니다.',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'평가 실행',exact:true})).toBeDisabled();expect(calls).toEqual([]);
});

async function evaluationFixture(page:Page){
 await page.clock.install();await setup(page);
 let reads=0,details=0,fail=false,status='RUNNING',pending:Promise<void>|undefined;
 await page.route('**/api/twin/evaluations**',async route=>{
  if(new URL(route.request().url()).pathname.endsWith('/TEVAL-test')){details++;await route.fulfill({json:{id:'TEVAL-test',status:'INTERRUPTED',error:'가상 중단',rows:[]}});return;}
  reads++;if(pending)await pending;
  await route.fulfill(fail?{status:503,json:{error:'가상 일시 오류'}}:{json:[{id:'TEVAL-test',status,completed:2,sampleCount:6}]});
 });
 await page.getByRole('button',{name:'8 AI 성능 평가',exact:true}).click();await page.getByRole('button',{name:'평가 결과 새로고침',exact:true}).click();
 await expect(page.getByText('TEVAL-test · RUNNING',{exact:true})).toBeVisible();
 return {reads:()=>reads,details:()=>details,setFail:(v:boolean)=>{fail=v;},finish:()=>{status='INTERRUPTED';},hold:(p:Promise<void>|undefined)=>{pending=p;}};
}
test('evaluation polls summaries only, pauses outside the screen and on hidden tabs, loads detail on demand',async({page})=>{
 const f=await evaluationFixture(page);const first=f.reads();
 await page.clock.runFor(5100);await expect.poll(f.reads).toBe(first+1);expect(f.details()).toBe(0);
 await page.getByRole('button',{name:'1 인프라 맵',exact:true}).click();const away=f.reads();await page.clock.runFor(20000);expect(f.reads()).toBe(away);
 await page.getByRole('button',{name:'8 AI 성능 평가',exact:true}).click();
 await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'));});
 await page.clock.runFor(20000);expect(f.reads()).toBe(away);
 await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});document.dispatchEvent(new Event('visibilitychange'));});
 f.finish();await page.clock.runFor(5100);await expect(page.getByText('TEVAL-test · INTERRUPTED',{exact:true})).toBeVisible();
 const done=f.reads();await page.clock.runFor(20000);expect(f.reads()).toBe(done);expect(f.details()).toBe(0);
 await page.getByRole('button',{name:'평가 상세 결과 보기',exact:true}).click();await expect(page.getByText('가상 중단',{exact:true})).toBeVisible();expect(f.details()).toBe(1);
});
test('evaluation requests never overlap and failure stops polling until explicit refresh',async({page})=>{
 const f=await evaluationFixture(page);let release!:()=>void;f.hold(new Promise<void>(r=>release=r));const first=f.reads();
 await page.clock.runFor(5100);await expect.poll(f.reads).toBe(first+1);await page.clock.runFor(20000);expect(f.reads()).toBe(first+1);
 f.setFail(true);f.hold(undefined);release();await expect(page.getByText('평가 자동 조회 중지 · 결과 새로고침으로 재개할 수 있습니다.',{exact:true})).toBeVisible();
 const failed=f.reads();await page.clock.runFor(360000);expect(f.reads()).toBe(failed);
 f.setFail(false);await page.getByRole('button',{name:'평가 결과 새로고침',exact:true}).click();await expect(page.getByText('평가 자동 조회 중지 · 결과 새로고침으로 재개할 수 있습니다.',{exact:true})).toHaveCount(0);
 await page.clock.runFor(5100);await expect.poll(f.reads).toBe(failed+2);
});
